import json
import subprocess
from pathlib import Path


HERE = Path(__file__).resolve().parents[1]


def test_stale_compile_and_build_cannot_write_into_a_new_story():
    """A late operation from story A must leave story B's empty UI untouched."""
    script = r'''
const fs=require('fs'),vm=require('vm'),source=fs.readFileSync(process.argv[1],'utf8');
const nodes={},subs=[],timers=[]; let story={story_token:'A',project:'A'},compilePost,compilePoll,buildPost,jobRequests=0;
function node(){const classes=new Set();return {value:'',checked:false,disabled:false,textContent:'',dataset:{},children:[],classList:{add:x=>classes.add(x),remove:x=>classes.delete(x),toggle:(x,v)=>v?classes.add(x):classes.delete(x),contains:x=>classes.has(x)},appendChild(x){this.children.push(x);return x},removeChild(){this.children.shift()},get firstChild(){return this.children[0]},addEventListener(){},setAttribute(){},insertRow(){return node()},insertCell(){return node()},closest(){return null}}}
function $(s){return nodes[s]||(nodes[s]=node())} ['#rvDraftSelect','#rvStatus','#rvInstall','#rvCompile','#rvApproveAll','#rvValidate','#rvCards','#storyPlayer','#log','#go','#goAnnotate','#path','#proj','#bgq','#bgready','#backgroundRequestsPanel','#backgroundRequestList','#continueBackgroundBuild','#backgroundContinueHint','#hint','#s1info','#s2','#s3','#s4','#bggrid','#bgsel','#modelProfileSelect','#welcomePanel','#cast','#s2sum'].forEach($); $('input[name=anno]:checked').value='no';
const api={json(m,p){return {m,p}},async request(path){if(path==='/api/draft?token=draft-a')return {story_token:'A',draft_version:1,counts:{pending:0,blocking_errors:0},cards:[]};if(path==='/api/compile')return new Promise(r=>compilePost=r);if(path==='/api/build')return new Promise(r=>buildPost=r);if(path==='/api/job'){jobRequests++;return {state:'succeeded',running:false,done:true}};if(path==='/api/picker')return {file_token:'file-a'};if(path==='/api/stories/open')return {story_token:'A',project:'A'};if(path.startsWith('/api/analyze'))return {path:'a',lines:1,speakers:[],scenes:[]};if(path.startsWith('/api/guess'))return {};if(path.startsWith('/api/backgrounds'))return [];if(path.startsWith('/api/drafts'))return [{draft_token:'draft-a',story_token:'A',draft_version:1}];return []},poll(){return new Promise(r=>compilePoll=r)}};
const window={Api:api,StoryStore:{get:()=>story,set:v=>{story=v;subs.forEach(f=>f(v))},subscribe:f=>subs.push(f)},StoryUI:{StoryContextBar:function(){},StoryAssetStrip:function(){},RecentStories:function(){this.refresh=async()=>{}}},ModelSettings:{profilePayload:()=>({})},CardList:{renderCardList(){}},Player:function(){this.pause=()=>{};this.loadCards=()=>{};this.jumpToCard=()=>{}},addEventListener(){}};
const document={querySelector:$,querySelectorAll:()=>[],createElement:node,createDocumentFragment:node,addEventListener(){}};vm.runInNewContext(source,{window,document,localStorage:{getItem(){},setItem(){},removeItem(){}},setTimeout:f=>timers.push(f),console});
(async()=>{$('#rvDraftSelect').value='draft-a';await window.AppRuntime.loadReview();const compiling=window.AppRuntime.compile();await new Promise(setImmediate);window.StoryStore.set({story_token:'B',project:'B'});compilePost({ok:true,build_id:'old',job_id:'j'});await compiling;const afterCompile={install:$('#rvInstall').disabled,status:$('#rvStatus').textContent};window.StoryStore.set({story_token:'A',project:'A'});$('#path').value='a';await window.AppRuntime.analyze();const building=window.AppRuntime.build();await new Promise(setImmediate);window.StoryStore.set({story_token:'B',project:'B'});buildPost({ok:true});await building;console.log(JSON.stringify({afterCompile,go:$('#go').disabled,oldBuildJobRequests:jobRequests,story:story.story_token}));})();
'''
    result = json.loads(subprocess.check_output(["node", "-e", script, str(HERE / "js" / "app.js")], text=True, encoding="utf-8"))
    assert result["afterCompile"]["install"] is True
    assert result["go"] is True
    assert result["oldBuildJobRequests"] == 0
    assert result["story"] == "B"


def test_browse_dialog_focuses_on_open_and_restores_trigger_on_escape():
    script = r'''
const fs=require('fs'),vm=require('vm'),source=fs.readFileSync(process.argv[1],'utf8');
const nodes={},listeners={};let active=null;function n(){const c=new Set();return {value:'',checked:false,disabled:false,textContent:'',dataset:{},classList:{toggle:(x,v)=>v?c.add(x):c.delete(x),add:x=>c.add(x),remove:x=>c.delete(x),contains:x=>c.has(x)},children:[],appendChild(x){this.children.push(x);return x},removeChild(){this.children.shift()},get firstChild(){return this.children[0]},addEventListener(){},setAttribute(){},closest(){return this},focus(){active=this},querySelector(){return nodes['#closeBrowse']}}}function $(x){return nodes[x]||(nodes[x]=n())}['#mBrowse','#closeBrowse','#browseTitle','#bdir','#chooseCurrentDir','#blist','#bgq','#bgready','#rvDraftSelect','#modelProfileSelect','#recentStories','#storyContextBar','#storyAssetStrip'].forEach($);const document={querySelector:$,querySelectorAll:()=>[],createElement:n,createDocumentFragment:n,addEventListener:(k,f)=>listeners[k]=f,get activeElement(){return active}};const window={Api:{request:async()=>({dir:'',files:[],dirs:[]}),json:()=>({})},StoryStore:{get:()=>null,set(){},subscribe(){}},StoryUI:{StoryContextBar:function(){},StoryAssetStrip:function(){},RecentStories:function(){this.refresh=async()=>{}}},ModelSettings:{profilePayload:()=>({})},addEventListener(){}};vm.runInNewContext(source,{window,document,localStorage:{getItem(){},setItem(){},removeItem(){}},setTimeout(){},console,URLSearchParams});const trigger=n();trigger.dataset.action='open-script';listeners.click({target:trigger});Promise.resolve().then(()=>{const opened={shown:$('#mBrowse').classList.contains('on'),focused:active===$('#closeBrowse')};listeners.keydown({key:'Escape'});console.log(JSON.stringify({opened,closed:!$('#mBrowse').classList.contains('on'),restored:active===trigger}));});
'''
    result = json.loads(subprocess.check_output(["node", "-e", script, str(HERE / "js" / "app.js")], text=True, encoding="utf-8"))
    assert result == {"opened": {"shown": True, "focused": True}, "closed": True, "restored": True}


def test_analyze_last_request_wins_when_a_is_slow_and_b_is_fast():
    script = r'''
const fs=require('fs'),vm=require('vm'),s=fs.readFileSync(process.argv[1],'utf8');const ns={},subs=[];let story=null,resolveA,resolveB;function n(){return {value:'',checked:false,disabled:false,textContent:'',dataset:{},classList:{toggle(){},add(){},remove(){}},children:[],appendChild(x){this.children.push(x);return x},removeChild(){this.children.shift()},get firstChild(){return this.children[0]},addEventListener(){},setAttribute(){},insertRow(){return n()},insertCell(){return n()},closest(){return null}}}function $(x){return ns[x]||(ns[x]=n())}['#path','#proj','#s1info','#s2','#s3','#s4','#cast','#s2sum','#bgq','#bgready','#bggrid','#go','#hint','#backgroundRequestsPanel','#continueBackgroundBuild','#backgroundContinueHint','#rvDraftSelect','#rvStatus','#rvInstall','#rvCompile','#rvApproveAll','#rvValidate','#rvCards','#storyPlayer','#log','#goAnnotate','#bgsel','#modelProfileSelect','#welcomePanel','#recentStories','#storyContextBar','#storyAssetStrip'].forEach($);$('input[name=anno]:checked').value='no';const api={json:(m,p)=>({p}),async request(p,o){if(p==='/api/picker')return new Promise(r=>o.p.path==='A'?resolveA=r:resolveB=r);if(p==='/api/stories/open')return {story_token:o.p.file_token,project:o.p.file_token};if(p.startsWith('/api/analyze'))return {path:p.includes('B')?'B':'A',lines:p.includes('B')?22:11,speakers:[],scenes:[]};if(p.startsWith('/api/guess'))return {};if(p.startsWith('/api/backgrounds'))return [];if(p==='/api/drafts')return [];return {profiles:[]}}};const w={Api:api,StoryStore:{get:()=>story,set:v=>{story=v;subs.forEach(f=>f(v))},subscribe:f=>subs.push(f)},StoryUI:{StoryContextBar:function(){},StoryAssetStrip:function(){},RecentStories:function(){this.refresh=async()=>{}}},ModelSettings:{profilePayload:()=>({})},CardList:{renderCardList(){}},Player:function(){this.pause=()=>{};this.loadCards=()=>{}},addEventListener(){}};const d={querySelector:$,querySelectorAll:()=>[],createElement:n,createDocumentFragment:n,addEventListener(){}};vm.runInNewContext(s,{window:w,document:d,localStorage:{getItem(){},setItem(){},removeItem(){}},setTimeout(){},console,URLSearchParams});(async()=>{$('#path').value='A';const a=w.AppRuntime.analyze();await Promise.resolve();$('#path').value='B';const b=w.AppRuntime.analyze();await Promise.resolve();resolveB({file_token:'B'});await b;resolveA({file_token:'A'});await a;console.log(JSON.stringify({story:story.story_token,path:$('#path').value,info:$('#s1info').textContent,go:$('#go').disabled}));})();
'''
    result = json.loads(subprocess.check_output(["node", "-e", script, str(HERE / "js" / "app.js")], text=True, encoding="utf-8"))
    assert result["story"] == "B"
    assert result["path"] == "B"
    assert "22" in result["info"]
    assert result["go"] is False


def test_build_poll_retries_first_and_midstream_network_failures_without_unlocking():
    script = r'''
const fs=require('fs'),vm=require('vm'),s=fs.readFileSync(process.argv[1],'utf8');const ns={},subs=[],timers=[];let story={story_token:'A',project:'A'},builds=0,jobs=[];function n(){return {value:'',checked:false,disabled:false,textContent:'',dataset:{},classList:{toggle(){},add(){},remove(){}},children:[],appendChild(x){this.children.push(x);return x},removeChild(){this.children.shift()},get firstChild(){return this.children[0]},addEventListener(){},setAttribute(){},insertRow(){return n()},insertCell(){return n()},closest(){return null}}}function $(x){return ns[x]||(ns[x]=n())}['#path','#proj','#s1info','#s2','#s3','#s4','#cast','#s2sum','#bgq','#bgready','#bggrid','#go','#hint','#backgroundRequestsPanel','#continueBackgroundBuild','#backgroundContinueHint','#rvDraftSelect','#rvStatus','#rvInstall','#rvCompile','#rvApproveAll','#rvValidate','#rvCards','#storyPlayer','#log','#goAnnotate','#bgsel','#modelProfileSelect','#welcomePanel','#recentStories','#storyContextBar','#storyAssetStrip'].forEach($);$('input[name=anno]:checked').value='no';const api={json:(m,p)=>({p}),async request(p,o){if(p==='/api/picker')return {file_token:'A'};if(p==='/api/stories/open')return story;if(p.startsWith('/api/analyze'))return {path:'A',lines:1,speakers:[],scenes:[]};if(p.startsWith('/api/guess'))return {};if(p.startsWith('/api/backgrounds'))return [];if(p==='/api/build'){builds++;return {ok:true}}if(p==='/api/job'){const next=jobs.shift();if(next instanceof Error)throw next;return next}if(p==='/api/drafts')return [];return {profiles:[]}}};const w={Api:api,StoryStore:{get:()=>story,set:v=>{story=v;subs.forEach(f=>f(v))},subscribe:f=>subs.push(f)},StoryUI:{StoryContextBar:function(){},StoryAssetStrip:function(){},RecentStories:function(){this.refresh=async()=>{}}},ModelSettings:{profilePayload:()=>({})},CardList:{renderCardList(){}},Player:function(){this.pause=()=>{};this.loadCards=()=>{}},addEventListener(){}};const d={querySelector:$,querySelectorAll:()=>[],createElement:n,createDocumentFragment:n,addEventListener(){}};vm.runInNewContext(s,{window:w,document:d,localStorage:{getItem(){},setItem(){},removeItem(){}},setTimeout:f=>timers.push(f),console,URLSearchParams});(async()=>{$('#path').value='A';await w.AppRuntime.analyze();jobs=[new Error('offline'),{state:'succeeded',running:false,done:true}];await w.AppRuntime.build();const firstLocked={go:$('#go').disabled,retry:$('#log').textContent.includes('连接'),builds};await w.AppRuntime.build();while(timers.length)await timers.shift()();const firstDone={go:$('#go').disabled,builds};jobs=[{state:'running',running:true,done:false},new Error('offline'),{state:'succeeded',running:false,done:true}];await w.AppRuntime.build();const midRunning={go:$('#go').disabled,builds};await timers.shift()();const midRetry={go:$('#go').disabled,retry:$('#log').textContent.includes('连接'),builds};while(timers.length)await timers.shift()();console.log(JSON.stringify({firstLocked,firstDone,midRunning,midRetry,final:{go:$('#go').disabled,builds}}));})();
'''
    result = json.loads(subprocess.check_output(["node", "-e", script, str(HERE / "js" / "app.js")], text=True, encoding="utf-8"))
    assert result["firstLocked"] == {"go": True, "retry": True, "builds": 1}
    assert result["firstDone"] == {"go": False, "builds": 1}
    assert result["midRunning"] == {"go": True, "builds": 2}
    assert result["midRetry"] == {"go": True, "retry": True, "builds": 2}
    assert result["final"] == {"go": False, "builds": 2}
